CREATE TABLE artifact_objects (
 id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY, tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, workspace_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
 created_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, requested_audience VARCHAR(8) NOT NULL CHECK(requested_audience IN('admin','portal')),
 requested_epoch BIGINT NOT NULL CHECK(requested_epoch>0), membership_authority CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
 execution_epoch BIGINT NOT NULL CHECK(execution_epoch>0), execution_membership CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
 creation_key CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, fingerprint VARBINARY(32) NOT NULL CHECK(OCTET_LENGTH(fingerprint)=32),
 store_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, name VARCHAR(200) NOT NULL, purpose VARCHAR(24) NOT NULL CHECK(purpose IN('model_bundle','dataset_source')),
 expected_bytes BIGINT NOT NULL CHECK(expected_bytes BETWEEN 1 AND 5497558138880), sha256 VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL CHECK(REGEXP_LIKE(sha256,'^[a-f0-9]{64}$','c')),
 part_bytes BIGINT NOT NULL CHECK(part_bytes BETWEEN 5242880 AND 5368709120),
 state VARCHAR(16) NOT NULL CHECK(state IN('creating','uploading','completing','ready','deleting','deleted','aborting','aborted')),
 remote_upload_id VARCHAR(4096), remote_etag VARCHAR(1024),
 operation_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin, operation_kind VARCHAR(16), operation_phase VARCHAR(16), operation_expires_at DATETIME(6), operation_authority JSON,
 error_code VARCHAR(64), revision BIGINT NOT NULL DEFAULT 1 CHECK(revision>0),
 upload_expires_at DATETIME(6) NOT NULL, expires_at DATETIME(6) NOT NULL,
 created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
 UNIQUE(tenant_id,workspace_id,id), UNIQUE(tenant_id,workspace_id,created_by,creation_key),
 FOREIGN KEY(tenant_id,workspace_id) REFERENCES workspaces(tenant_id,id), FOREIGN KEY(created_by) REFERENCES users(id),
 CHECK((operation_id IS NULL)=(operation_kind IS NULL)), CHECK((operation_id IS NULL)=(operation_phase IS NULL)),
 CHECK(operation_phase IS NULL OR operation_phase IN('prepared','sent')),
 CHECK(operation_kind IS NULL OR operation_kind IN('create','part','complete','delete','abort','ingest')),
 CHECK(state<>'ready' OR remote_etag IS NOT NULL), CHECK((operation_id IS NULL)=(operation_expires_at IS NULL)),
 CHECK(expires_at>=upload_expires_at), CHECK((expected_bytes+part_bytes-1) DIV part_bytes<=10000),
 CHECK((operation_id IS NULL)=(operation_authority IS NULL)),
 KEY artifact_objects_scope_page(tenant_id,workspace_id,created_at DESC,id DESC),
 CONSTRAINT aobj_id CHECK(REGEXP_LIKE(id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
 CONSTRAINT aobj_tenant_id CHECK(REGEXP_LIKE(tenant_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
 CONSTRAINT aobj_workspace_id CHECK(REGEXP_LIKE(workspace_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
 CONSTRAINT aobj_created_by CHECK(REGEXP_LIKE(created_by,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
 CONSTRAINT aobj_creation_key CHECK(REGEXP_LIKE(creation_key,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
 CONSTRAINT aobj_store_id CHECK(REGEXP_LIKE(store_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
 CONSTRAINT aobj_membership_authority CHECK(membership_authority IS NULL OR REGEXP_LIKE(membership_authority,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
 CONSTRAINT aobj_execution_membership CHECK(execution_membership IS NULL OR REGEXP_LIKE(execution_membership,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
 CONSTRAINT aobj_operation_id CHECK(operation_id IS NULL OR REGEXP_LIKE(operation_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;